// Claude's review tests for A42 (the sample project) in the browser. agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject, type Mock } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function openPanel(mocks: Mock[]): Promise<{ page: Page; panel: Page }> {
  const project = newProject('p1', fixture.origin);
  project.scenarios[0]!.mocks.push(...mocks);
  await session.setState({ ...emptyState(), projects: [project], enabledOrigins: [fixture.origin] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  return { page, panel };
}

const product = (page: Page) =>
  page.evaluate(async () => {
    const r = await fetch('/api/products/42');
    return { status: r.status, mocked: r.headers.get('content-type'), body: await r.text() };
  });

test('the empty Mocks tab offers the sample; it serves the page, and Undo takes it away', async () => {
  const { page, panel } = await openPanel([]);
  try {
    await expect(panel.getByTestId('mocks-empty')).toBeVisible();
    await panel.getByTestId('mocks-empty').getByTestId('sample-load').click();

    for (const name of ['Default', 'Checkout down', 'Slow network']) {
      await expect(panel.getByTestId('scenario-chip').filter({ hasText: name })).toHaveCount(1);
    }
    await expect(panel.getByTestId('sample-tip')).toHaveText('Try it in the Test bar: GET /api/products/42');
    await expect(panel.getByTestId('mocks-empty')).toHaveCount(0);

    await expect.poll(async () => (await product(page)).status).toBe(200);
    expect((await product(page)).body).toContain('42');

    await panel.getByTestId('undo').click();
    await expect(panel.getByTestId('mocks-empty')).toBeVisible();
    await expect(panel.getByTestId('scenario-chip').filter({ hasText: 'Checkout down' })).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the toolbar adds the sample next to existing mocks, never replacing them', async () => {
  const mine: Mock = {
    id: 'mine', name: 'Mine', enabled: true, method: 'GET', urlPattern: '/api/goals', source: 'manual', createdAt: 0,
    response: { status: 200, headers: {}, body: 'mine', bodyEncoding: 'text', delayMs: 0 },
  };
  const { page, panel } = await openPanel([mine]);
  try {
    await expect(panel.getByTestId('mocks-empty')).toHaveCount(0);
    await panel.getByTestId('sample-load-toolbar').click();
    await expect(panel.getByTestId('scenario-chip').filter({ hasText: 'Slow network' })).toHaveCount(1);
    await expect(panel.getByText('Mine', { exact: true })).toBeVisible();
    const goals = await page.evaluate(async () => (await fetch('/api/goals')).text());
    expect(goals).toBe('mine');
  } finally {
    await panel.close();
    await page.close();
  }
});
